from typing import *
class Solution:
    def countPairs(self, nums: List[int], k: int) -> int:
        counter = Counter(nums)
        ans = 0
        for num, freq in counter.items():
            if num % k == 0:
                # Count pairs (i, j) where i * j is divisible by k
                ans += freq * (freq - 1) // 2
            else:
                # Count pairs (i, j) where i * j is divisible by k
                for divisor in range(1, k):
                    if num % divisor == 0:
                        quotient = num // divisor
                        if quotient % k == 0:
                            ans += freq * counter[quotient]
                            break
        return ans

class Solution:
    def shortestAlternatingPaths(self, n: int, redEdges: List[List[int]], blueEdges: List[List[int]]) -> List[int]:
        # Create a graph using adjacency list
        graph = [[] for _ in range(n)]
        for r, b in redEdges:
            graph[r].append(b)
        for r, b in blueEdges:
            graph[b].append(r)

        # Initialize distances for each node to infinity
        distances = [-1] * n
        distances[0] = 0

        # Perform BFS starting from node 0
        queue = deque([(0, 'r')])
        while queue:
            node, color = queue.popleft()
            for neighbor in graph[node]:
                if color == 'r':
                    if distances[neighbor] != -1:
                        continue
                    distances[neighbor] = distances[node] + 1
                    queue.append((neighbor, 'b'))
                else:
                    if distances[neighbor] != -1:
                        continue
                    distances[neighbor] = distances[node] + 1
                    queue.append((neighbor, 'r'))

        return distances

