import math

class Solution:
    def countPairs(self, nums: List[int], k: int) -> int:
        gcds = [math.gcd(num, k) for num in nums]
        gcd_count = Counter(gcds)
        total_pairs = 0

        for i, gcd_i in enumerate(gcds):
            for j, gcd_j in gcd_count.items():
                if i < nums.index(j) and (gcd_i * gcd_j) % k == 0:
                    total_pairs += gcd_count[j]

        return total_pairs

from typing import List

class Solution:
    def oddEvenJumps(self, arr: List[int]) -> int:
        n = len(arr)
        next_greater = [-1] * n
        next_smaller = [-1] * n

        stack = []
        for i in range(n):
            while stack and arr[i] > arr[stack[-1]]:
                next_greater[stack.pop()] = i
            stack.append(i)

        stack.clear()
        for i in range(n-1, -1, -1):
            while stack and arr[i] >= arr[stack[-1]]:
                next_smaller[stack.pop()] = i
            stack.append(i)

        odd_jump = [False] * n
        even_jump = [False] * n
        odd_jump[n-1] = True
        even_jump[n-1] = True

        for i in range(n-2, -1, -1):
            if next_greater[i] != -1:
                even_jump[i] = odd_jump[next_greater[i]]
            if next_smaller[i] != -1:
                odd_jump[i] = even_jump[next_smaller[i]]

        return sum(odd_jump)

from collections import defaultdict

class Solution:
    def minTrioDegree(self, n: int, edges: List[List[int]]) -> int:
        # Create a graph
        graph = defaultdict(list)
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)

        # Initialize variables to store the minimum degree and the trio
        min_degree = float('inf')
        trio = []

        # Iterate through each node in the graph
        for node in range(n):
            # Check if the node has at least 3 neighbors
            if len(graph[node]) >= 3:
                # Iterate through each pair of neighbors
                for i in range(len(graph[node])):
                    for j in range(i + 1, len(graph[node])):
                        # Calculate the degree of the current trio
                        degree = len(graph[node]) - 2
                        # Update the minimum degree and the trio if the current trio has a smaller degree
                        if degree < min_degree:
                            min_degree = degree
                            trio = [node, graph[node][i], graph[node][j]]

        # Return the minimum degree of a connected trio
        return min_degree if trio else -1

class Solution:
    def getMaxGridHappiness(self, m: int, n: int, introvertsCount: int, extrovertsCount: int) -> int:
        from functools import lru_cache

        @lru_cache(None)
        def dfs(row, prev_state, introverts_left, extroverts_left):
            if row == m:
                return 0

            max_happiness = 0
            current_state = 0

            for col in range(n):
                mask = 1 << col
                if introverts_left > 0:
                    happiness = 120
                    if prev_state & mask:
                        happiness -= 30 * 2
                    if prev_state & (mask << 1):
                        happiness -= 30
                    if prev_state & (mask >> 1):
                        happiness -= 30
                    if prev_state & (mask << n):
                        happiness -= 30
                    if prev_state & (mask >> n):
                        happiness -= 30
                    current_state |= mask
                    max_happiness = max(max_happiness, happiness + dfs(row, current_state, introverts_left - 1, extroverts_left))

                if extroverts_left > 0:
                    happiness = 40
                    if prev_state & mask:
                        happiness += 20 * 2
                    if prev_state & (mask << 1):
                        happiness += 20
                    if prev_state & (mask >> 1):
                        happiness += 20
                    if prev_state & (mask << n):
                        happiness += 20
                    if prev_state & (mask >> n):
                        happiness += 20
                    current_state |= mask
                    max_happiness = max(max_happiness, happiness + dfs(row, current_state, introverts_left, extroverts_left - 1))

            max_happiness = max(max_happiness, dfs(row + 1, 0, introverts_left, extroverts_left))
            return max_happiness

        return dfs(0, 0, introvertsCount, extrovertsCount)

class Solution:
    def dividePlayers(self, skill: List[int]) -> int:
        n = len(skill)
        if n % 2 != 0:
            return -1

        skill.sort()
        total_skill = sum(skill)
        half = n // 2

        for i in range(half):
            team_skill = skill[i] * skill[i + 1]
            if team_skill != total_skill:
                return -1

        return sum(skill[i] * skill[i + 1] for i in range(half))

