class Solution:
    def paintWalls(self, cost: List[int], time: List[int]) -> int:
        n = len(cost)
        dp = [[float('inf')] * (n+1) for _ in range(n+1)]
        dp[0][0] = 0

        for i in range(1, n+1):
            for j in range(i+1):
                dp[i][j] = min(dp[i-1][j], dp[i][j-1] + cost[i-1])
                if j > 0:
                    dp[i][j] = min(dp[i][j], dp[i-time[i-1]][j-1])

        return dp[n][n]

