class Solution:
    def maxSubstringLength(self, s: str) -> int:
        n = len(s)
        last_occurrence = {char: i for i, char in enumerate(s)}
        max_length = -1

        for start in range(n):
            seen = set()
            valid = True
            for end in range(start, n):
                char = s[end]
                if char in seen or (last_occurrence[char] > end and last_occurrence[char] != end):
                    valid = False
                    break
                seen.add(char)
            if valid:
                max_length = max(max_length, end - start + 1)

        return max_length if max_length > 1 else -1

class Solution:
    def cherryPickup(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        @lru_cache(None)
        def dfs(i, j):
            if i == m-1 and j == n-1:
                return 0
            ans = float('-inf')
            for k in range(max(0, i+1), min(m, i+1)+1):
                for l in range(max(0, j+1), min(n, j+1)+1):
                    ans = max(ans, grid[i][j] + dfs(k, l))
            return ans

        return dfs(0, 0)

