class Solution:
    def countSubarrays(self, nums: List[int], k: int) -> int:
        index_of_k = nums.index(k)
        balance = 0
        prefix_count = defaultdict(int)
        prefix_count[0] = 1

        for i in range(index_of_k + 1, len(nums)):
            if nums[i] < k:
                balance -= 1
            else:
                balance += 1
            prefix_count[balance] += 1

        balance = 0
        result = 0

        for i in range(index_of_k, -1, -1):
            if nums[i] < k:
                balance -= 1
            else:
                balance += 1

            result += prefix_count[balance]
            result += prefix_count[balance - 1]

        return result

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def deleteNode(self, root: Optional[TreeNode], key: int) -> Optional[TreeNode]:
        # Base case: if the root is None, return None
        if not root:
            return None

        # If the key is less than the current node's value, recursively delete from the left subtree
        if key < root.val:
            root.left = self.deleteNode(root.left, key)

        # If the key is greater than the current node's value, recursively delete from the right subtree
        elif key > root.val:
            root.right = self.deleteNode(root.right, key)

        # If the key is equal to the current node's value, delete the node
        else:
            # Case 1: No children
            if not root.left and not root.right:
                return None

            # Case 2: One child
            if root.left:
                return root.left
            if root.right:
                return root.right

            # Case 3: Two children
            temp = root.left
            while temp.right:
                temp = temp.right
            temp.right = root.right
            return root.left

