from collections import deque

class Solution:
    def maxResult(self, nums: List[int], k: int) -> int:
        q = deque([(nums[0], 0)])
        res = nums[0]
        for i in range(1, len(nums)):
            while q and q[0][1] < i - k:
                q.popleft()
            res = max(res, nums[i] + q[0][0])
            while q and nums[q[-1][1]] < nums[i]:
                q.pop()
            q.append((nums[i], i))
        return res

from collections import defaultdict

class Solution:
    def friendRequests(self, n: int, restrictions: List[List[int]], requests: List[List[int]]) -> List[bool]:
        graph = defaultdict(list)
        visited = set()
        for i in range(n):
            graph[i] = []

        # Build the graph
        for x, y in restrictions:
            graph[x].append(y)
            graph[y].append(x)

        def dfs(node):
            if node in visited:
                return False

            visited.add(node)
            for neighbor in graph[node]:
                if not dfs(neighbor):
                    return False
            return True

        ans = []
        for u, v in requests:
            if dfs(u) and dfs(v):
                ans.append(True)
            else:
                ans.append(False)

        return ans

