class Solution:
    def decodeCiphertext(self, encodedText: str, rows: int) -> str:
        n = len(encodedText)
        cols = n // rows

        # Create a matrix to hold the encoded text
        matrix = [[''] * cols for _ in range(rows)]

        # Fill the matrix based on the encoded text
        index = 0
        for i in range(rows):
            for j in range(cols):
                matrix[i][j] = encodedText[index]
                index += 1

        # Read the decoded text from the matrix
        decodedText = ''
        for j in range(cols):
            for i in range(rows):
                decodedText += matrix[i][j]

        return decodedText.rstrip()

from collections import defaultdict

class Solution:
    def loudAndRich(self, richer: List[List[int]], quiet: List[int]) -> List[int]:
        # Create a graph representation of richer relationships
        graph = defaultdict(list)
        for u, v in richer:
            graph[v].append(u)

        # Initialize the result array with the original quiet values
        res = list(quiet)

        # Perform DFS to find the least quiet person for each person
        for i in range(len(res)):
            self.dfs(graph, i, res, quiet)

        return res

    def dfs(self, graph, node, res, quiet):
        # If the result for this node is already computed, return it
        if res[node] != float('inf'):
            return

        # Set the current node's result to its own quiet value
        res[node] = quiet[node]

        # Explore neighbors
        for neighbor in graph[node]:
            # Recursively find the least quiet person for the neighbor
            self.dfs(graph, neighbor, res, quiet)

            # Update the result for the current node if finding a quieter neighbor
            if res[neighbor] < res[node]:
                res[node] = res[neighbor]

class Solution:
    def findMaximumLength(self, nums: List[int]) -> int:
        n = len(nums)
        dp = [1] * n
        max_len = 1

        for i in range(1, n):
            for j in range(i):
                if sum(nums[j:i+1]) >= nums[i]:
                    dp[i] = max(dp[i], dp[j] + 1)
                    break
            max_len = max(max_len, dp[i])

        return max_len

