class Solution:
    def calculate(self, s: str) -> int:
        stack = []
        num = 0
        sign = 1

        for char in s:
            if char.isdigit():
                num = num * 10 + int(char)
            elif char == '+' or char == '-':
                stack.append(num * sign)
                num = 0
                sign = 1 if char == '+' else -1
            elif char == '(':
                stack.append(sign)
                stack.append(0)
                sign = 1
            elif char == ')':
                prev_sign = stack.pop()
                prev_num = stack.pop()
                num = prev_num + prev_sign * num
                sign = prev_sign

        stack.append(num * sign)
        return sum(stack)

class Solution:
    def getMaxGridHappiness(self, m: int, n: int, introvertsCount: int, extrovertsCount: int) -> int:
        from functools import lru_cache

        def get_happiness_diff(last_row, row, i):
            diff = 0
            if row[i] == 1:
                diff += 120
            elif row[i] == 2:
                diff += 40

            if i > 0 and row[i] != 0:
                if row[i-1] == 1:
                    diff -= 30
                elif row[i-1] == 2:
                    diff += 20
                if row[i] == 1:
                    diff -= 30
                elif row[i] == 2:
                    diff += 20

            if last_row[i] != 0:
                if row[i] == 1:
                    diff -= 30
                elif row[i] == 2:
                    diff += 20
                if last_row[i] == 1:
                    diff -= 30
                elif last_row[i] == 2:
                    diff += 20

            return diff

        @lru_cache(None)
        def dp(row_index, introverts_left, extroverts_left, last_row):
            if row_index == m or (introverts_left == 0 and extroverts_left == 0):
                return 0

            max_happiness = 0
            for i1 in range(introverts_left + 1):
                for i2 in range(extroverts_left + 1 - i1):
                    row = [0] * n
                    for j in range(i1):
                        row[j] = 1
                    for j in range(i1, i1 + i2):
                        row[j] = 2

                    current_happiness = 0
                    for i in range(n):
                        current_happiness += get_happiness_diff(last_row, tuple(row), i)

                    max_happiness = max(max_happiness, current_happiness + dp(row_index + 1, introverts_left - i1, extroverts_left - i2, tuple(row)))

            return max_happiness

        return dp(0, introvertsCount, extrovertsCount, tuple([0] * n))

class Solution:
    def findKthNumber(self, n: int, k: int) -> int:
        current = 1
        while k > 1:
            steps = min(n // current, k) * (current + 1)
            if steps == k:
                current += 1
            else:
                k -= steps
                current *= 10
        return current

class Solution:
    def countPairs(self, nums: List[int], low: int, high: int) -> int:
        def count_prefixes(x):
            cnt = [0] * 31
            for bit in range(31):
                if x & (1 << bit):
                    cnt[bit] += 1
            return tuple(cnt)

        from collections import defaultdict
        prefix_count = defaultdict(int)
        result = 0

        for num in nums:
            prefix = count_prefixes(num)
            # Count pairs with xor in [0, low-1]
            for p in prefix_count:
                if all(a <= b for a, b in zip(p, prefix)):
                    result += prefix_count[p]
            # Count pairs with xor in [low, high]
            for p in prefix_count:
                if all(a <= b for a, b in zip(p, prefix)) and sum(a <= b for a, b in zip(p, prefix)) >= low:
                    result += prefix_count[p]
            prefix_count[prefix] += 1

        return result

