class Solution:
    def minAreaRect(self, points: List[List[int]]) -> int:
        n = len(points)
        if n < 4:
            return 0

        point_set = set(tuple(p) for p in points)
        min_area = float('inf')

        for i in range(n):
            x1, y1 = points[i]
            for j in range(i + 1, n):
                x2, y2 = points[j]

                # Check if the line segment between (x1, y1) and (x2, y2) intersects with any other points
                if (x1, y2) in point_set and (x2, y1) in point_set:
                    # Calculate the area of the rectangle
                    width = abs(x2 - x1)
                    height = abs(y2 - y1)
                    min_area = min(min_area, width * height)

        return min_area if min_area != float('inf') else 0

class Solution:
    def minimumAddedCoins(self, coins: List[int], target: int) -> int:
        coins.sort()
        added_coins = 0
        current_sum = 0

        for coin in coins:
            if current_sum >= target:
                break

            if coin > current_sum + 1:
                needed_coin = current_sum + 1
                added_coins += needed_coin - current_sum - 1
                current_sum += needed_coin
            else:
                current_sum += coin

        while current_sum < target:
            added_coins += target - current_sum
            current_sum += target - current_sum

        return added_coins

