import numpy as np

class Solution:
    def getMinDistSum(self, positions: List[List[int]]) -> float:
        def distance(x):
            return sum(np.sqrt((np.array(positions) - x)**2).sum(axis=1))

        result = minimize(distance, np.mean(positions, axis=0), method='L-BFGS-B', bounds=[(0, 100), (0, 100)])
        return result.fun

from typing import List

class Solution:
    def maximumLength(self, nums: List[int], k: int) -> int:
        n = len(nums)
        dp = [[0] * 2 for _ in range(n)]
        dp[0][0] = 1

        for i in range(1, n):
            dp[i][0] = max(dp[i-1]) + 1
            dp[i][1] = dp[i-1][0] + 1 if nums[i] != nums[i-1] else 0

        max_length = max(dp[-1])
        changes = k

        for i in range(1, n):
            if nums[i] != nums[i-1]:
                max_length = max(max_length, dp[i-1][0] + 1 + changes)
                changes -= 1
                if changes < 0:
                    break

        return max_length

class Solution:
    def rearrangeString(self, s: str, k: int) -> str:
        # Count the frequency of each character in the string
        char_count = {}
        for char in s:
            if char in char_count:
                char_count[char] += 1
            else:
                char_count[char] = 1

        # Find the maximum frequency
        max_freq = max(char_count.values())

        # If the maximum frequency is less than or equal to k, return an empty string
        if max_freq <= k:
            return ""

        # Sort the characters by their frequency in descending order
        sorted_chars = sorted(char_count.items(), key=lambda x: x[1], reverse=True)

        # Create the rearranged string
        result = []
        for i in range(max_freq):
            for char, count in sorted_chars:
                if count > 0:
                    result.extend([char] * count)
                    count -= 1

        return ''.join(result)

class Solution:
    def partitionArray(self, nums: List[int], k: int) -> int:
        n = len(nums)
        nums.sort()
        count = 0
        for i in range(n):
            if nums[i] - nums[i-1] > k:
                count += 1
                nums[i] = nums[i-1]
        return count + 1

class Solution:
    def longestDecomposition(self, text: str) -> int:
        n = len(text)
        left, right = 0, n - 1
        count = 0

        while left < right:
            l, r = left, right
            while l < r:
                if text[l:r+1] == text[left:right+1]:
                    break
                r -= 1

            if l == r:
                count += 1
                left = right + 1
                right = n - 1
            else:
                count += 2
                left = r + 1
                right -= 1

        if left <= right:
            count += 1

        return count

class Solution:
    def minimumCost(self, sentence: str, k: int) -> int:
        words = sentence.split()
        n = len(words)

        # dp[i] will store the minimum cost to split the first i+1 words
        dp = [float('inf')] * n

        for i in range(n):
            current_length = 0
            for j in range(i, -1, -1):
                current_length += len(words[j])
                if current_length + (i - j) > k:
                    break
                if j == 0:
                    dp[i] = 0
                else:
                    dp[i] = min(dp[i], dp[j-1] + (k - current_length - (i - j)) ** 2)

        # The last row's cost is not included, so we subtract the last row's cost
        last_row_length = 0
        for j in range(n-1, -1, -1):
            last_row_length += len(words[j])
            if last_row_length + (n - 1 - j) > k:
                break

        return dp[n-1] - (k - last_row_length - (n - 1 - j)) ** 2 if j != n-1 else 0

import heapq

class Solution:
    def maxPoints(self, grid: List[List[int]], queries: List[int]) -> List[int]:
        m, n = len(grid), len(grid[0])
        visited = set()
        directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]
        pq = []
        heapq.heappush(pq, (grid[0][0], 0, 0))
        points = [0] * len(queries)
        query_index = 0

        while pq:
            value, x, y = heapq.heappop(pq)
            if (x, y) in visited:
                continue
            visited.add((x, y))
            if value < queries[query_index]:
                points[query_index] += 1

            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < m and 0 <= ny < n and (nx, ny) not in visited:
                    heapq.heappush(pq, (grid[nx][ny], nx, ny))

            if query_index + 1 < len(queries) and value >= queries[query_index + 1]:
                query_index += 1

        return points

