class Solution:
    def numberOfPairs(self, nums1: List[int], nums2: List[int], k: int) -> int:
        count = 0
        nums2_counts = Counter(nums2)

        for num in nums1:
            for multiple in range(k, num + 1, k):
                if multiple % k == 0:
                    divisor = multiple // k
                    count += nums2_counts[divisor]

        return count

