class Solution:
    def numberOfArrays(self, differences: List[int], lower: int, upper: int) -> int:
        min_val = float('inf')
        max_val = float('-inf')

        for diff in differences:
            min_val = min(min_val, lower + diff)
            max_val = max(max_val, upper + diff)

        if min_val > upper or max_val < lower:
            return 0

        return max(0, max_val - min_val + 1)

