# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def zigzagLevelOrder(self, root: Optional[TreeNode]) -> List[List[int]]:
        if not root:
            return []

        result = []
        queue = deque([root])
        left_to_right = True

        while queue:
            level_size = len(queue)
            current_level = deque()

            for _ in range(level_size):
                node = queue.popleft()

                if left_to_right:
                    current_level.append(node.val)
                else:
                    current_level.appendleft(node.val)

                if node.left:
                    queue.append(node.left)
                if node.right:
                    queue.append(node.right)

            result.append(list(current_level))
            left_to_right = not left_to_right

        return result

class Solution:
    def movesToMakeZigzag(self, nums: List[int]) -> int:
        n = len(nums)
        if n <= 1:
            return 0

        # Function to calculate the cost of making the array zigzag
        def cost(arr):
            total_cost = 0
            for i in range(1, n):
                if i % 2 == 0:
                    if arr[i] >= arr[i - 1]:
                        total_cost += arr[i - 1] - arr[i] + 1
                        arr[i] = arr[i - 1] - 1
                else:
                    if arr[i] >= arr[i - 1]:
                        total_cost += arr[i - 1] - arr[i] + 1
                        arr[i] = arr[i - 1] - 1
            return total_cost

        # Calculate costs for both possible zigzag patterns
        cost1 = cost(nums.copy())
        cost2 = cost([x - 1 for x in nums])

        # Return the minimum cost
        return min(cost1, cost2)

class Solution:
    def numberOfSubarrays(self, nums: List[int], k: int) -> int:
        count = 0
        left = 0
        odd_count = 0

        for right in range(len(nums)):
            if nums[right] % 2 == 1:
                odd_count += 1

            while odd_count > k:
                if nums[left] % 2 == 1:
                    odd_count -= 1
                left += 1

            count += right - left + 1

        return count

