class Solution:
    def transformArray(self, arr: List[int]) -> List[int]:
        for i in range(1, len(arr)):
            if arr[i] < arr[i - 1] and arr[i] < arr[i + 1]:
                arr[i] += 1
            elif arr[i] > arr[i - 1] and arr[i] > arr[i + 1]:
                arr[i] -= 1
        return arr

class Solution:
    def watchedVideosByFriends(self, watchedVideos: List[List[str]], friends: List[List[int]], id: int, level: int) -> List[str]:
        n = len(watchedVideos)
        queue = deque([id])
        visited = set([id])
        level_count = 0

        # BFS to find people at the given level
        while queue:
            size = len(queue)
            for _ in range(size):
                cur_id = queue.popleft()
                if level_count == level:
                    break
                for friend_id in friends[cur_id]:
                    if friend_id not in visited:
                        visited.add(friend_id)
                        queue.append(friend_id)
            level_count += 1

        # Count the frequency of each video
        video_count = defaultdict(int)
        for friend_id in visited:
            for video in watchedVideos[friend_id]:
                video_count[video] += 1

        # Sort videos by frequency and alphabetically
        sorted_videos = sorted(video_count.items(), key=lambda x: (x[1], x[0]))

        # Extract the video names
        result = [video for video, _ in sorted_videos]
        return result

class Solution:
    def removeOnes(self, grid: List[List[int]]) -> bool:
        # Iterate through each row and column
        for i in range(len(grid)):
            for j in range(len(grid[0])):
                # Flip the value in the current row and column
                grid[i][j] = 1 - grid[i][j]

        # Check if all elements in the grid are now 0
        return all(row == 0 for row in grid)

class Solution:
    def evaluate(self, s: str, knowledge: List[List[str]]) -> str:
        knowledge_dict = {k: v for k, v in knowledge}
        result = []
        i = 0

        while i < len(s):
            if s[i] == '(':
                start = i + 1
                while s[start] != ')':
                    start += 1
                key = s[start - 1:start]
                result.append(knowledge_dict.get(key, '?'))
                i = start
            else:
                result.append(s[i])
                i += 1

        return ''.join(result)

