class Solution:
    def findLeastNumOfUniqueInts(self, arr: List[int], k: int) -> int:
        counter = Counter(arr)
        while k > 0:
            if not counter:
                return 0
            min_val = min(counter.values())
            if k < min_val:
                return len(counter) - k + 1
            counter -= {k: min_val}
            k -= min_val
        return len(counter)

class Solution:
    def makeTheIntegerZero(self, num1: int, num2: int) -> int:
        if num1 < num2:
            return -1

        target = num1 // num2
        current = num1
        for i in range(target, -1, -1):
            current -= i * num2
            if current == 0:
                return i
            elif current < 0:
                return -1

