class Solution:
    def getBiggestThree(self, grid: List[List[int]]) -> List[int]:
        m, n = len(grid), len(grid[0])
        max_heap = []
        unique_sums = set()

        def add_to_heap(val):
            if val not in unique_sums:
                unique_sums.add(val)
                heapq.heappush(max_heap, val)
                if len(max_heap) > 3:
                    unique_sums.remove(heapq.heappop(max_heap))

        for i in range(m):
            for j in range(n):
                add_to_heap(grid[i][j])  # Add single cell rhombus

                # Try different sizes of rhombus
                size = 1
                while True:
                    if i - size < 0 or i + size >= m or j - size < 0 or j + size >= n:
                        break

                    total = 0
                    # Top to right
                    for k in range(size):
                        total += grid[i - size + k][j - size + k]

                    # Right to bottom
                    for k in range(1, size + 1):
                        total += grid[i + k][j + size - k]

                    # Bottom to left
                    for k in range(1, size + 1):
                        total += grid[i + size - k][j - k]

                    # Left to top
                    for k in range(1, size):
                        total += grid[i - k][j - size + k]

                    add_to_heap(total)
                    size += 1

        return sorted(max_heap, reverse=True)

class Solution:
    def numberOfSubarrays(self, nums: List[int], k: int) -> int:
        left = 0
        right = 0
        count = 0
        odd_count = 0

        while right < len(nums):
            if nums[right] % 2 != 0:
                odd_count += 1

            # If the window size exceeds k, move the left pointer to the right
            while odd_count > k:
                if nums[left] % 2 == 0:
                    odd_count -= 1
                left += 1

            # Add the size of the current window to the count
            count += right - left + 1

            right += 1

        return count

class Solution:
    def removeBoxes(self, boxes: List[int]) -> int:
        @functools.lru_cache(None)
        def dp(i, j, k):
            if i > j:
                return 0
            while j > i and boxes[j] == boxes[j - 1]:
                j -= 1
                k += 1
            return (k + 1) ** 2 + dp(j + 1, i, 0)

        return dp(0, len(boxes) - 1, 0)

