class Solution:
    def minimumHammingDistance(self, source: List[int], target: List[int], allowedSwaps: List[List[int]]) -> int:
        parent = list(range(len(source)))
        rank = [0] * len(source)
        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]
        def union(x, y):
            px, py = find(x), find(y)
            if px == py:
                return False
            if rank[px] < rank[py]:
                parent[px] = py
            elif rank[px] > rank[py]:
                parent[py] = px
            else:
                parent[py] = px
                rank[px] += 1
            return True
        graph = defaultdict(list)
        for u, v in allowedSwaps:
            graph[u].append(v)
            graph[v].append(u)
        def dfs(node):
            visited.add(node)
            res = [source[node]]
            for neighbor in graph[node]:
                if neighbor not in visited:
                    res.extend(dfs(neighbor))
            return res
        visited = set()
        components = {}
        for node in range(len(source)):
            if node not in visited:
                component = dfs(node)
                components[tuple(component)] = sum([source[i] != target[i] for i in component])
        min_distance = float('inf')
        for component, distance in components.items():
            min_distance = min(min_distance, distance)
        return min_distance

