class Solution:
    def simulationResult(self, windows: List[int], queries: List[int]) -> List[int]:
        index_map = {window: i for i, window in enumerate(windows)}
        for query in queries:
            current_index = index_map[query]
            windows.pop(current_index)
            windows.insert(0, query)
            index_map[query] = 0
            for key in index_map:
                if index_map[key] > current_index:
                    index_map[key] -= 1
        return windows

