class Solution:
    def lengthOfLongestSubstringTwoDistinct(self, s: str) -> int:
        # Initialize a dictionary to store the last seen index of each character
        char_index = {}
        # Initialize variables to track the maximum length of the valid substring
        max_length = 0
        left = 0

        # Iterate through the string with a right pointer
        for right in range(len(s)):
            # If the character has been seen before, move the left pointer to the right until the character is no longer seen
            while char_index[s[right]] > left:
                char_index[s[left]] -= 1
                left += 1

            # Update the maximum length of the valid substring
            max_length = max(max_length, right - left + 1)

        return max_length

