class Solution:
    def maximumPoints(self, edges: List[List[int]], coins: List[int], k: int) -> int:
        from collections import defaultdict

        # Build the graph
        graph = defaultdict(list)
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)

        # Memoization dictionary
        memo = {}

        def dfs(node, parent, halved):
            if (node, halved) in memo:
                return memo[(node, halved)]

            # Calculate coins available at this node after halving
            available_coins = coins[node] >> halved

            # Option 1: Collect all coins with deduction
            option1 = available_coins - k

            # Option 2: Collect half the coins and reduce subtree coins
            option2 = available_coins // 2
            for neighbor in graph[node]:
                if neighbor != parent:
                    option2 += dfs(neighbor, node, halved + 1)

            # Choose the better option
            result = max(option1, option2)
            memo[(node, halved)] = result
            return result

        # Start DFS from the root node (0)
        return dfs(0, -1, 0)

class Solution:
    def shoppingOffers(self, price: List[int], special: List[List[int]], needs: List[int]) -> int:
        # Sort special by price in descending order
        special.sort(key=lambda x: x[-1])

        # Initialize total cost to 0
        total_cost = 0

        # Iterate over each special offer
        for offer in special:
            # Check if the current offer can be used
            if all(needs[i] >= offer[i] for i in range(len(needs))):
                # Calculate the cost of the current offer
                cost = sum(price[i] * offer[i] for i in range(len(price)))

                # Update the total cost if this offer is cheaper
                if cost < total_cost:
                    total_cost = cost

        return total_cost

