class Solution:
    def crackSafe(self, n: int, k: int) -> str:
        if n == 1:
            return ''.join(str(i) for i in range(k))

        visited = set()
        path = '0' * (n - 1)

        while len(visited) < k ** n:
            node = path[-(n - 1):]
            for num in range(k - 1, -1, -1):
                candidate = node + str(num)
                if candidate not in visited:
                    visited.add(candidate)
                    path += str(num)
                    break

        return path

