class Solution:
    def countSubarrays(self, nums: List[int], k: int) -> int:
        def count_ones(x):
            return bin(x).count('1')

        max_bits = max(nums + [k]).bit_length()
        bit_count = [0] * max_bits
        current_and = (1 << max_bits) - 1
        left = 0
        result = 0

        for right in range(len(nums)):
            for i in range(max_bits):
                if nums[right] & (1 << i) == 0:
                    bit_count[i] += 1
                    if bit_count[i] == 1:
                        current_and &= ~(1 << i)

            while left <= right and current_and < k:
                for i in range(max_bits):
                    if nums[left] & (1 << i) == 0:
                        bit_count[i] -= 1
                        if bit_count[i] == 0:
                            current_and |= (1 << i)
                left += 1

            if current_and == k:
                result += left + 1

        return result

