class Solution:
    def largestIsland(self, grid: List[List[int]]) -> int:
        def dfs(x, y, island_id):
            if x < 0 or x >= len(grid) or y < 0 or y >= len(grid) or grid[x][y] != 1:
                return 0
            grid[x][y] = island_id
            return 1 + dfs(x + 1, y, island_id) + dfs(x - 1, y, island_id) + dfs(x, y + 1, island_id) + dfs(x, y - 1, island_id)

        n = len(grid)
        island_id = 2
        island_sizes = {}

        for i in range(n):
            for j in range(n):
                if grid[i][j] == 1:
                    size = dfs(i, j, island_id)
                    island_sizes[island_id] = size
                    island_id += 1

        max_size = max(island_sizes.values(), default=0)

        for i in range(n):
            for j in range(n):
                if grid[i][j] == 0:
                    neighbors = set()
                    if i > 0 and grid[i - 1] > 1:
                        neighbors.add(grid[i - 1])
                    if i < n - 1 and grid[i + 1] > 1:
                        neighbors.add(grid[i + 1])
                    if j > 0 and grid[i][j - 1] > 1:
                        neighbors.add(grid[i][j - 1])
                    if j < n - 1 and grid[i][j + 1] > 1:
                        neighbors.add(grid[i][j + 1])

                    new_size = 1 + sum(island_sizes[neighbor] for neighbor in neighbors)
                    max_size = max(max_size, new_size)

        return max_size

from collections import defaultdict

class Solution:
    def maximalPathQuality(self, values: List[int], edges: List[List[int]], maxTime: int) -> int:
        graph = defaultdict(list)

        # Build the graph
        for u, v, time in edges:
            graph[u].append((v, time))
            graph[v].append((u, time))

        self.max_quality = 0

        def dfs(node, time, visited):
            if node == 0:
                self.max_quality = max(self.max_quality, sum(values[n] for n in visited))

            for neighbor, weight in graph[node]:
                if time + weight <= maxTime:
                    visited.add(neighbor)
                    dfs(neighbor, time + weight, visited)
                    visited.remove(neighbor)

        dfs(0, 0, {0})
        return self.max_quality

class Solution:
    def maxNumberOfFamilies(self, n: int, reservedSeats: List[List[int]]) -> int:
        # Create a set to store the reserved seats
        reserved = set()
        # Iterate through each row of seats
        for row in reservedSeats:
            # Add the reserved seat numbers to the set
            reserved.add(row[0])
            reserved.add(row[1])

        # Initialize the count of four-person groups
        count = 0

        # Iterate through each row of seats
        for row in reservedSeats:
            # If the current row has fewer than 4 seats, skip it
            if len(row) < 4:
                continue
            # Check if the current row has 4 consecutive seats
            if row[0] == row[1] == row[2] == row[3]:
                count += 1
            # Check if the current row has 5 consecutive seats
            elif row[0] == row[1] == row[2] == row[3] == row[4]:
                count += 2
            # Check if the current row has 6 consecutive seats
            elif row[0] == row[1] == row[2] == row[3] == row[4] == row[5]:
                count += 3

        return count

class Solution:
    def sumOfPower(self, nums: List[int], k: int) -> int:
        MOD = 10**9 + 7
        n = len(nums)

        # Initialize DP table
        dp = [[0] * (k + 1) for _ in range(n + 1)]
        dp[0][0] = 1

        for i in range(1, n + 1):
            num = nums[i - 1]
            for j in range(k + 1):
                if j >= num:
                    dp[i][j] = (dp[i][j] + dp[i - 1][j - num]) % MOD
                dp[i][j] = (dp[i][j] + dp[i - 1][j]) % MOD

        return dp[n][k]

class Solution:
    def numKLenSubstrNoRepeats(self, s: str, k: int) -> int:
        n = len(s)
        if n < k:
            return 0

        count = 0
        char_map = {}
        left = 0

        for right in range(n):
            while char_map.get(s[right], 0) > 0:
                char_map[s[left]] -= 1
                left += 1

            char_map[s[right]] += 1
            if right - left + 1 == k:
                count += 1
                char_map[s[left]] -= 1
                left += 1

        return count

