class Solution:
    def maxProfit(self, prices: List[int], profits: List[int]) -> int:
        n = len(prices)
        max_profit = -1

        # Arrays to store the maximum profit up to each index from the left and right
        left_max_profit = [-1] * n
        right_max_profit = [-1] * n

        # Fill left_max_profit array
        min_price = prices[0]
        for i in range(1, n):
            if prices[i] > min_price:
                left_max_profit[i] = max(left_max_profit[i-1], profits[i] - min_price)
            else:
                left_max_profit[i] = left_max_profit[i-1]
            min_price = min(min_price, prices[i])

        # Fill right_max_profit array
        max_price = prices[-1]
        for i in range(n-2, -1, -1):
            if prices[i] < max_price:
                right_max_profit[i] = max(right_max_profit[i+1], profits[i] + max_price)
            else:
                right_max_profit[i] = right_max_profit[i+1]
            max_price = max(max_price, prices[i])

        # Calculate the maximum profit for the triplet
        for j in range(1, n-1):
            if left_max_profit[j] != -1 and right_max_profit[j] != -1:
                max_profit = max(max_profit, left_max_profit[j] + profits[j] + right_max_profit[j] - profits[j])

        return max_profit

