class Solution:
    def getWordsInLongestSubsequence(self, words: List[str], groups: List[int]) -> List[str]:
        n = len(words)
        dp = [[False] * n for _ in range(n)]

        # Initialize the DP table
        for i in range(n):
            dp[i][i] = True

        # Fill the DP table
        for i in range(1, n):
            for j in range(i):
                if words[i] == words[j] and groups[i] != groups[j]:
                    dp[i][j] = dp[j][i-1]

        # Find the longest subsequence
        max_length = 0
        result = []

        for i in range(n):
            if dp[i][n-1]:
                result.append(words[i])
                max_length += 1

        return result

class Solution:
    def equationsPossible(self, equations: List[str]) -> bool:
        # Build a dictionary to store the equivalence groups
        group = {}

        # Function to find the root of a node
        def find(x):
            if x != group[x]:
                group[x] = find(group[x])
            return group[x]

        # Function to union two nodes into the same group
        def union(x, y):
            root_x = find(x)
            root_y = find(y)
            if root_x != root_y:
                group[root_x] = root_y

        # Process the equations
        for eq in equations:
            if eq[1] == '=':
                union(ord(eq[0]), ord(eq[3]))

        # Check the remaining equations
        for eq in equations:
            if eq[1] == '!' and find(ord(eq[0])) == find(ord(eq[3])):
                return False

        return True
